def parse_demos(text):
    out=[]
    pat=re.compile(r'Demo pair (\d+) (input|output) \((\d+)x(\d+)\):\n')
    matches=list(pat.finditer(text))
    for m in matches:
        n,kind,h,w=map(int,[m.group(1), 0, m.group(3),m.group(4)]) if False else (int(m.group(1)),m.group(2),int(m.group(3)),int(m.group(4)))
        start=m.end(); rows=[]
        for line in text[start:].splitlines():
            if len(rows)==h: break
            vals=[int(x) for x in line.split()]
            if len(vals)!=w: break
            rows.append(vals)
        if len(rows)!=h: print('bad', n,kind,len(rows),h)
        out.append((n,kind,rows))
    pairs={}
    for n,k,g in out: pairs.setdefault(n,{})[k]=g
    return pairs
