def group_analysis(g):
    cnt=Counter(x for row in g for x in row); bg=cnt.most_common(1)[0][0]
    cs=[(col,pts,norm_shape(pts),is_perfect_L(pts)) for col,pts in components(g) if col!=bg]
    marks=[v for v in cs if v[3] and len(v[1])>=6]
    marker=max(marks,key=lambda v:len(v[1]))
    mset=marker[1]
    groups=defaultdict(list)
    for v in cs:
      if v is not marker: groups[v[2]].append(v)
    def dist(v):
      return min(abs(y-y2)+abs(x-x2) for y,x in v[1] for y2,x2 in mset)
    res=[]
    for sig,vs in groups.items():
      if len(vs)>=2:
        far=max(vs,key=dist)
