import math

def centers_group_analysis(g):
    bg=Counter(x for row in g for x in row).most_common()[0][0]
    cs=[(col,pts,norm_shape(pts),is_perfect_L(pts)) for col,pts in components(g) if col!=bg]
    mark=max([x for x in cs if x[3] and len(x[1])>=6], key=lambda x:len(x[1]))
    my=sum(y for y,x in mark[1])/len(mark[1]); mx=sum(x for y,x in mark[1])/len(mark[1])
    groups=defaultdict(list)
    for v in cs:
        if v is mark: continue
        groups[v[2]].append(v)
    candidates=[]
    for sig,vs in groups.items():
        if len(vs)>=2:
            for v in vs:
                cy=sum(y for y,x in v[1])/len(v[1]); cx=sum(x for y,x in v[1])/len(v[1])
                d=math.hypot(cy-my,cx-mx)
                candidates.append((d,len(sig),len(vs),v[0],min(y for y,x in v[1]),min(x for y,x in v[1]),sig))
    return sorted(candidates,reverse=True)
for n in sorted(pairs):
    print('\n',n,centers_group_analysis(pairs[n]['input'])[:5])

